  const out=lookup(src,map);
  if(out===null){ const lang=localStorage.getItem('aranyaLanguage')||'en'; if(lang!=='en') queueRemote(node,src,lang,full.match(/^\s*/)[0],full.match(/\s*$/)[0]); return; }
